! Rectangular solid section w/ equal reinforcement at each side (RSe)
! Function returning reinforcement area (As)

function As_RSe(b,h,c,fcd,N,Mx,My)

    implicit none

    real(kind=8) :: As_RSe,b,h,c,fcd,N,Mx,My
    real(kind=8) :: bh,cb,ni,mix,miy,fyd

    bh = b/h
    cb = c/b
    ni = N/b/h/fcd
    mix = Mx/b/h/h/fcd
    miy = My/b/b/h/fcd
    fyd = 500000/1.15d0

    As_RSe = w_RSe(bh,cb,ni,mix,miy)*b*h*fcd/fyd

end function As_RSe

! Rectangular hollow section w/ equal reinforcement at each side (RHe)
! Function returning reinforcement mechanical ratio (w)

function w_RHe(bh,tb,n,mx,my)

    implicit none

    real(kind=8) :: w_RHe,bh,tb,n,mx,my
    value :: mx,my
    real(kind=8) :: mx2,my2,mxmy,m,mx_b,my_b,m_b,a,w
    real(kind=8) :: bh_n,tb_n,n_n,mx_n,my_n,m_n,mx2_n,my2_n,mxmy_n,a_n
    real(kind=8) :: n_1_1,n_1_2,n_1_3,n_1_4,n_1_5,n_1_6,n_1_7,n_1_8,n_1_9,n_1_10,n_1_11,n_1_12,n_1_13,n_1_14,n_1_15,n_1_16,n_1_17,n_1_18,n_1_19,n_1_20,n_1_21,n_1_22,n_1_23,n_1_24,n_1_25,n_1_26,n_1_27,n_1_28,n_1_29,n_1_30,n_1_31,n_1_32,n_1_33,n_1_34,n_1_35
    real(kind=8) :: n_2_1,n_2_2,n_2_3,n_2_4,n_2_5,n_2_6,n_2_7,n_2_8,n_2_9,n_2_10,n_2_11,n_2_12,n_2_13,n_2_14,n_2_15,n_2_16,n_2_17,n_2_18,n_2_19,n_2_20,n_2_21,n_2_22,n_2_23,n_2_24,n_2_25,n_2_26,n_2_27,n_2_28,n_2_29,n_2_30,w_n,n_2_31,n_2_32,n_2_33,n_2_34,n_2_35

    if (.not.((bh >= 1.0d0).and.(bh <= 2.0d0).and.(tb >= 0.05d0).and.(tb <= 0.20d0).and.(n <= 0.1d0).and.(n >= -0.6d0))) then
        w_RHe = ieee_value(1.d0,ieee_quiet_nan)
        return
    endif

    ! moment sign is irrelevant (doubly symmetric section)
    mx = abs(mx)
    my = abs(my)

    w = ieee_value(1.d0,ieee_quiet_nan)

    bh_n = (bh-1.0d0)/1.05d0
    tb_n = (tb-0.05d0)/0.16d0
    n_n = (n+0.6d0)/0.7d0

    ! surface boundary

    a = atan2(my,mx)
    a_n = a/1.570796d0
    n_1_1 = 1/(1+dexp(-(+0.569232d0*bh_n+0.792279d0*tb_n-3.724095d0*n_n+0.492927d0*a_n-0.714055d0)))
    n_1_2 = 1/(1+dexp(-(-2.018367d0*bh_n-0.051450d0*tb_n-0.137103d0*n_n+2.926904d0*a_n+0.805681d0)))
    n_1_3 = 1/(1+dexp(-(-0.049986d0*bh_n-0.310344d0*tb_n-2.334396d0*n_n+0.016734d0*a_n+1.498608d0)))
    n_1_4 = 1/(1+dexp(-(+0.313742d0*bh_n+0.245765d0*tb_n-2.346217d0*n_n+1.024962d0*a_n-0.324828d0)))
    n_1_5 = 1/(1+dexp(-(+0.169971d0*bh_n+0.085103d0*tb_n-2.472546d0*n_n-1.921892d0*a_n+1.657546d0)))
    n_2_1 = 1/(1+dexp(-(+3.959550d0*n_1_1-1.994738d0*n_1_2-4.604882d0*n_1_3-2.359537d0*n_1_4+0.759166d0*n_1_5+1.463995d0)))
    n_2_2 = 1/(1+dexp(-(+1.086193d0*n_1_1+0.163554d0*n_1_2+0.969785d0*n_1_3-7.650345d0*n_1_4+4.408769d0*n_1_5-1.162781d0)))
    n_2_3 = 1/(1+dexp(-(-3.049988d0*n_1_1-0.191338d0*n_1_2+3.330137d0*n_1_3+6.074831d0*n_1_4-4.780727d0*n_1_5-2.126750d0)))
    n_2_4 = 1/(1+dexp(-(-3.578072d0*n_1_1-3.444666d0*n_1_2+7.157969d0*n_1_3+3.140098d0*n_1_4-0.972285d0*n_1_5-4.425132d0)))
    n_2_5 = 1/(1+dexp(-(-5.548974d0*n_1_1-2.579811d0*n_1_2+4.675226d0*n_1_3-3.309691d0*n_1_4-3.936810d0*n_1_5-0.137154d0)))
    m_n = -1.696831d0*n_2_1+1.406773d0*n_2_2+1.269600d0*n_2_3+1.263737d0*n_2_4+2.144630d0*n_2_5-0.216417d0
    m_b = m_n*0.23549d0+0.195207d0
    mx2 = mx*mx
    my2 = my*my
    mxmy = mx*my
    m = sqrt(mx2+my2)

    if (m <= m_b) then

